import terms from '@/data/terms.json';

// Purdue Banner codes: Fall 2026 -> 202710, Spring 2026 -> 202620 (same as harmonize.py)
export const termCode = (term) => {
  const [season, year] = term.split(' ');
  return season === 'Fall' ? `${Number(year) + 1}10` : `${year}20`;
};

// Generated by server/harmonize.py: the newest term with data
export const CURRENT_SEMESTER = terms.current.name;
export const CURRENT_SEMESTER_CODE = terms.current.code;

// Terms the schedule assistant can plan, oldest first. The data pipeline scrapes and
// pins sections for the newest 2 terms, so this must stay in sync with data.yml.
export const SCHEDULE_SEMESTERS = terms.all.slice(0, 2).reverse()
  .map(name => ({ name, code: termCode(name) }));

// Schedule state (pinned courses, chosen sections, open course) is saved per term.
export const semesterStorageKey = (key, code) => `${key}:${code}`;

// Before per-term storage the schedule only planned terms.json's current term under
// unsuffixed keys. That was Fall 2026 until mid-October 2026 and is Spring 2027 after, so
// old plans could be for either schedule term: copy them into each so none are lost.
export const migrateScheduleStorage = () => {
  for (const key of ['pinnedCourses', 'selectedLectures', 'selectedCourse']) {
    const legacy = localStorage.getItem(key);
    if (legacy === null) continue;
    for (const { code } of SCHEDULE_SEMESTERS) {
      const scoped = semesterStorageKey(key, code);
      if (localStorage.getItem(scoped) === null) localStorage.setItem(scoped, legacy);
    }
    localStorage.removeItem(key);
  }
};

// Whether a course runs in `termName`, and if not, the most useful thing to say instead:
// the other schedule term it does run in ("Fall 2026 only"), or when it last ran.
export const offering = (courseTerms = [], termName) => {
  if (courseTerms.includes(termName)) return { offered: true };
  const other = SCHEDULE_SEMESTERS.find(option => option.name !== termName && courseTerms.includes(option.name));
  if (other) return { offered: false, other, label: `${other.name} only` };
  // terms.json lists terms newest first
  const last = terms.all.find(name => courseTerms.includes(name));
  return { offered: false, other: null, last, label: last ? `Last offered ${last}` : 'Not offered recently' };
};
